<template>
  <div class="min-h-screen bg-gray-50 px-4 py-5 dark:bg-gray-900 sm:px-6 lg:px-8">
    <PageHeader :title="`Penutupan Berkas${berkas?.judulBerkas ? `: ${berkas.judulBerkas}` : ''}`" :items="[{ label: 'Kelola' }, { label: 'Pemeliharaan' }, { label: 'Pemberkasan', to: '/kelola/pemeliharaan/pemberkasan/berkas-saya' }, { label: 'Penutupan' }]" />
    <div v-if="isLoading" class="flex min-h-96 items-center justify-center"><UIcon name="i-lucide-loader-circle" class="size-8 animate-spin text-primary-500" /></div>
    <template v-else>
      <div class="mb-6 grid grid-cols-1 gap-6 xl:grid-cols-3">
        <UCard class="overflow-hidden xl:col-span-2" :ui="{ body: 'p-0 sm:p-0' }">
          <div class="border-l-4 border-primary-500 p-5 sm:p-7">
            <div class="mb-7 flex flex-wrap items-start justify-between gap-4"><div><div class="mb-1 flex items-center gap-2 text-primary-600 dark:text-primary-400"><UIcon name="i-lucide-folder-archive" class="size-5" /><span class="text-sm font-semibold uppercase tracking-wider">Informasi Berkas</span></div><p class="text-sm text-gray-500 dark:text-gray-400">Detail metadata berkas yang akan ditutup.</p></div><UBadge color="warning" variant="soft" size="lg" class="gap-1.5 rounded-full"><UIcon name="i-lucide-info" class="size-4" />{{ statusLabel }}</UBadge></div>
            <div class="grid grid-cols-1 gap-x-8 gap-y-6 sm:grid-cols-2"><div v-for="item in metadata" :key="item.label" class="min-w-0"><p class="mb-1 text-xs font-medium uppercase tracking-wider text-gray-500 dark:text-gray-400">{{ item.label }}</p><p class="truncate text-base font-semibold text-gray-900 dark:text-white" :title="item.value">{{ item.value }}</p></div></div>
          </div>
        </UCard>
        <UCard><template #header><div class="flex items-center justify-between gap-3"><div><h2 class="text-lg font-semibold text-gray-900 dark:text-white">Alur Verifikasi</h2><p class="mt-1 text-xs text-gray-500 dark:text-gray-400">Tentukan pihak yang memverifikasi berkas.</p></div><UButton v-if="verifikatorList.length < 3" icon="i-lucide-user-round-plus" variant="outline" size="sm" @click="addVerifikator"><span class="hidden sm:inline">Tambah</span></UButton></div></template>
          <div class="space-y-0"><div v-for="(v, idx) in verifikatorList" :key="idx" class="relative pb-5 last:pb-0"><div v-if="idx < verifikatorList.length - 1" class="absolute left-4 top-8 h-[calc(100%-1.5rem)] w-px bg-gray-200 dark:bg-gray-700" /><div class="relative flex gap-3"><div class="flex size-8 shrink-0 items-center justify-center rounded-full border-2 border-primary-500 bg-primary-50 text-sm font-bold text-primary-600 dark:bg-primary-950 dark:text-primary-300">{{ idx + 1 }}</div><div class="min-w-0 flex-1"><div class="mb-2 flex items-center justify-between gap-2"><p class="text-sm font-semibold text-gray-900 dark:text-white">{{ stepLabel(idx) }}</p><UButton v-if="idx > 0" icon="i-lucide-trash-2" color="error" variant="ghost" size="xs" aria-label="Hapus verifikator" @click="removeVerifikator(idx)" /></div><USelectMenu v-model="v.verifikator_persnum" :items="optionsFor(idx)" value-key="value" label-key="label" searchable searchable-placeholder="Cari nama, jabatan, atau persnum..." placeholder="Pilih verifikator..." class="w-full" :disabled="!verifikatorOptions.length" @update:model-value="syncVerifikator(idx)"><template #item="{ item, selected }: any"><div class="flex min-w-0 items-start gap-2 py-1"><UIcon name="i-lucide-user-circle-2" class="mt-0.5 size-5 shrink-0 text-gray-400" /><div class="min-w-0 flex-1"><p class="truncate text-sm" :class="selected && 'font-semibold text-primary-600'">{{ item.label }}</p><p class="truncate text-xs text-gray-500">{{ item.positionText || 'Tanpa jabatan' }}</p></div><UIcon v-if="selected" name="i-lucide-check" class="size-4 shrink-0 text-primary-500" /></div></template></USelectMenu><p v-if="v.jabatan_verifikator" class="mt-1.5 text-xs text-gray-500 dark:text-gray-400">{{ v.jabatan_verifikator }}</p></div></div></div></div>
        </UCard>
      </div>
      <div class="grid grid-cols-1 gap-6 xl:grid-cols-3"><UCard class="xl:col-span-2"><template #header><h2 class="text-lg font-semibold text-gray-900 dark:text-white">Catatan Penutupan</h2></template><UTextarea v-model="catatan" :rows="7" autoresize class="w-full" placeholder="Tambahkan alasan penutupan atau catatan penting lainnya di sini..." /><p class="mt-2 text-xs text-gray-500 dark:text-gray-400">Catatan ini akan diteruskan kepada seluruh verifikator.</p></UCard><UCard class="self-start"><div class="space-y-3"><UButton block size="lg" icon="i-lucide-circle-check" :loading="isSubmitting" :disabled="!canSubmit" @click="handleSubmit">Ajukan Penutupan Berkas</UButton><UButton block variant="ghost" color="error" :to="detailPath">Batal</UButton><p v-if="!canSubmit && berkas?.status === 'aktif'" class="text-center text-xs text-amber-600 dark:text-amber-400">Pilih minimal satu verifikator yang berbeda.</p></div></UCard></div>
    </template>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
definePageMeta({ middleware: 'auth' });
const route = useRoute(); const router = useRouter(); const { getBerkasById, ajukanTutupBerkas } = useArsipDinamis(); const { apiGet } = useApi(); const toast = useToast();
const berkasId = computed(() => route.params.id as string); const detailPath = computed(() => `/kelola/pemeliharaan/pemberkasan/${berkasId.value}`); const berkas = ref<any>(null); const catatan = ref(''); const isLoading = ref(true); const isSubmitting = ref(false); const verifikatorOptions = ref<any[]>([]); const verifikatorList = ref([{ verifikator_persnum: '', verifikator_position_id: null, jabatan_verifikator: '' }]);
const selectedPersnums = computed(() => verifikatorList.value.map((v) => v.verifikator_persnum).filter(Boolean)); const canSubmit = computed(() => berkas.value?.status === 'aktif' && verifikatorList.value.every((v) => v.verifikator_persnum) && new Set(selectedPersnums.value).size === selectedPersnums.value.length); const statusLabel = computed(() => ({ aktif: 'Siap Ditutup', menunggu_verifikasi: 'Sedang Diverifikasi' }[berkas.value?.status] || 'Penutupan Berkas')); const display = (value: any) => value === null || value === undefined || value === '' ? '-' : String(value);
const metadata = computed(() => [{ label: 'Nama Berkas', value: display(berkas.value?.judulBerkas) }, { label: 'Kode Berkas', value: display(berkas.value?.kodeBerkas) }, { label: 'Retensi Aktif', value: `${berkas.value?.retensiAktifTahun || 0} Tahun` }, { label: 'Retensi Inaktif', value: `${berkas.value?.retensiInaktifTahun || 0} Tahun` }, { label: 'Lokasi Fisik', value: display(berkas.value?.lokasi) }, { label: 'Jumlah Naskah', value: `${berkas.value?.jumlahNaskah ?? berkas.value?.jumlah_naskah ?? 0} Dokumen` }]); const stepLabel = (idx: number) => idx === 0 ? 'Verifikator 1' : idx === 1 ? 'Verifikator 2' : `Verifikator ${idx + 1}`;
const optionsFor = (idx: number) => { const current = verifikatorList.value[idx]?.verifikator_persnum; const selected = new Set(verifikatorList.value.filter((_, i) => i !== idx).map((v) => v.verifikator_persnum).filter(Boolean)); return verifikatorOptions.value.filter((o) => o.value === current || !selected.has(o.value)); }; const syncVerifikator = (idx: number) => { const selected = verifikatorOptions.value.find((o) => o.value === verifikatorList.value[idx].verifikator_persnum); verifikatorList.value[idx].verifikator_position_id = selected?.positionId; verifikatorList.value[idx].jabatan_verifikator = selected?.positionText || ''; }; const addVerifikator = () => { if (verifikatorList.value.length < 3) verifikatorList.value.push({ verifikator_persnum: '', verifikator_position_id: null, jabatan_verifikator: '' }); }; const removeVerifikator = (idx: number) => verifikatorList.value.splice(idx, 1);
const handleSubmit = async () => { if (!canSubmit.value) return; isSubmitting.value = true; try { await ajukanTutupBerkas(berkasId.value, { verifikator: verifikatorList.value, catatan: catatan.value }); toast.add({ title: 'Pengajuan penutupan berhasil dikirim', color: 'success' }); router.push(detailPath.value); } catch (e: any) { const message = e?.response?.data?.message || e?.data?.message || e?.message; toast.add({ title: 'Gagal mengajukan penutupan', description: Array.isArray(message) ? message.join(', ') : message || 'Silakan coba kembali.', color: 'error' }); } finally { isSubmitting.value = false; } };
onMounted(async () => { try { const response: any = await getBerkasById(berkasId.value); berkas.value = response?.data ?? response; const people: any = await apiGet('/person/with-position/all', { params: { limit: 500 } }); const payload = people?.data ?? people; const list = Array.isArray(payload) ? payload : payload?.data ?? []; verifikatorOptions.value = list.map((p: any) => ({ label: `${p.nama || p.name} — ${p.position_text || 'Tanpa jabatan'} (${p.persnum})`, value: String(p.persnum), positionId: Number(p.position || p.position_id) || undefined, positionText: p.position_text || '' })); } catch (e) { console.error('Gagal memuat data:', e); toast.add({ title: 'Gagal memuat data penutupan', color: 'error' }); } finally { isLoading.value = false; } });
</script>
